const CONFIG = {
  apiBaseUrl: 'https://asesoriainmobiliariajb.com',
  apiPath: '/api/integrations/n8n/bancolombia/reconcile',
  internalEmail: 'pagos@REEMPLAZAR-DOMINIO.com',

  // Debe copiarse de un correo auténtico previamente verificado.
  allowedSenders: [
    'REEMPLAZAR-REMITENTE-REAL@bancolombia.com.co',
  ],

  // La fuente histórica aportado no contiene esta relación.
  // Configure las cuentas en Prisma y replique aquí los últimos 4 dígitos.
  receivingAccountLast4: ['0000'],
};

const raw = $input.first().json ?? {};

const pick = (...values) => {
  for (const value of values) {
    if (value !== undefined && value !== null && String(value).trim() !== '') {
      return value;
    }
  }
  return '';
};

const normalize = (value) =>
  String(value ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();

const htmlToText = (value) =>
  String(value ?? '')
    .replace(/<(br|\/p|\/div|\/tr|\/li)\b[^>]*>/gi, '\n')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/\r/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

const body = htmlToText(
  pick(
    raw.body?.content,
    raw.bodyContent,
    raw.html,
    raw.text,
    raw.bodyPreview,
    raw.snippet,
  ),
);

const subject = String(pick(raw.subject, raw.asunto)).trim();
const sender = normalize(
  pick(
    raw.from?.emailAddress?.address,
    raw.sender?.emailAddress?.address,
    raw.from?.address,
    raw.sender?.address,
    raw.from,
    raw.sender,
  ),
);

const outlookMessageId = String(
  pick(raw.id, raw.messageId, raw.internetMessageId),
).trim();

const internetMessageId = String(
  pick(raw.internetMessageId, raw.internet_message_id),
).trim();

const receivedAt = String(
  pick(raw.receivedDateTime, raw.date, new Date().toISOString()),
).trim();

const allowedSenders = CONFIG.allowedSenders
  .map(normalize)
  .filter((value) => value && !value.startsWith('reemplazar-'));

const accounts = CONFIG.receivingAccountLast4
  .map((value) => String(value).replace(/\D/g, '').slice(-4))
  .filter((value) => value.length === 4 && value !== '0000');

const senderAllowed = allowedSenders.includes(sender);
const fullText = `${subject}\n${body}`;
const normalizedText = normalize(fullText);

const parseMoney = (candidate) => {
  let value = String(candidate ?? '')
    .replace(/\s/g, '')
    .replace(/[^\d.,-]/g, '');

  if (!value || !/\d/.test(value)) return null;

  const lastDot = value.lastIndexOf('.');
  const lastComma = value.lastIndexOf(',');

  if (lastDot >= 0 && lastComma >= 0) {
    const decimal = lastDot > lastComma ? '.' : ',';
    const thousands = decimal === '.' ? ',' : '.';
    value = value.split(thousands).join('').replace(decimal, '.');
  } else if (lastComma >= 0) {
    const decimals = value.length - lastComma - 1;
    value =
      decimals === 1 || decimals === 2
        ? value.replace(/\./g, '').replace(',', '.')
        : value.replace(/,/g, '');
  } else if (lastDot >= 0) {
    const dots = (value.match(/\./g) || []).length;
    const decimals = value.length - lastDot - 1;
    if (dots > 1 || decimals === 3) value = value.replace(/\./g, '');
  }

  const amount = Number(value);
  return Number.isFinite(amount) && amount > 0 ? Math.round(amount) : null;
};

let amount = null;
const amountPatterns = [
  /(?:valor|monto|abono|pago|transferencia|consignaci[oó]n|recibiste)\s*(?:de|por|:|-)?\s*(?:cop|col\$|\$)?\s*([\d][\d.,\s]{2,24})/gi,
  /(?:cop|col\$|\$)\s*([\d][\d.,\s]{2,24})/gi,
];

for (const pattern of amountPatterns) {
  for (const match of fullText.matchAll(pattern)) {
    const parsed = parseMoney(match[1]);
    if (parsed && parsed < 1_000_000_000_000) {
      amount = parsed;
      break;
    }
  }
  if (amount) break;
}

const accountCandidates = [];
const accountPatterns = [
  /(?:cuenta|producto)\s*(?:destino|receptora|beneficiaria|abonada|n[uú]mero|no\.?)?\s*(?:es|:|-)?\s*([xX*#\d][xX*#\d\s-]{3,30})/gi,
  /(?:terminada|finalizada|finaliza|termina)\s+en\s+(\d{4})/gi,
];

for (const pattern of accountPatterns) {
  for (const match of fullText.matchAll(pattern)) {
    const digits = String(match[1]).replace(/\D/g, '');
    if (digits.length >= 4) accountCandidates.push(digits.slice(-4));
  }
}

const accountLast4 = accountCandidates.find((value) => accounts.includes(value)) || '';

const lines = body
  .split(/\n+/)
  .map((line) => line.trim())
  .filter(Boolean);

const clean = (value) =>
  String(value ?? '')
    .replace(/^[\s:–—-]+/, '')
    .replace(/\s{2,}/g, ' ')
    .trim();

const lineValue = (labels) => {
  for (const line of lines) {
    const normalizedLine = normalize(line);
    for (const label of labels) {
      const index = normalizedLine.indexOf(normalize(label));
      if (index >= 0) {
        const value = clean(line.slice(index + label.length));
        if (value && value.length <= 130) return value;
      }
    }
  }
  return '';
};

let payerName = lineValue([
  'nombre del pagador',
  'nombre de quien paga',
  'pagador',
  'ordenante',
  'enviado por',
  'transferido por',
  'de:',
]);

if (!payerName) {
  const match = fullText.match(
    /(?:pagador|ordenante|enviado por|transferido por)\s*(?:es|:|-)?\s*([A-ZÁÉÍÓÚÑ][A-ZÁÉÍÓÚÑa-záéíóúñ .'-]{3,100})/i,
  );
  payerName = clean(match?.[1] ?? '');
}

let bankReference = lineValue([
  'número de transacción',
  'numero de transaccion',
  'referencia bancaria',
  'referencia',
  'comprobante',
  'código de operación',
  'codigo de operacion',
]);

if (!bankReference) {
  const match = fullText.match(
    /(?:referencia|comprobante|transacci[oó]n|operaci[oó]n)\s*(?:n[uú]mero|no\.?|id|:|-)?\s*([A-Z0-9-]{5,50})/i,
  );
  bankReference = clean(match?.[1] ?? '');
}

const brandAndOperation =
  normalizedText.includes('bancolombia') &&
  ['pago', 'transferencia', 'abono', 'consignacion', 'recibiste'].some(
    (word) => normalizedText.includes(word),
  );

const errors = [];
if (!allowedSenders.length) errors.push('No se configuró el remitente exacto autorizado.');
if (!accounts.length) errors.push('No se configuraron las cuentas receptoras.');
if (!senderAllowed) errors.push('El remitente no está en la lista exacta autorizada.');
if (!brandAndOperation) errors.push('El mensaje no contiene marca y operación bancaria.');
if (!outlookMessageId) errors.push('No se obtuvo el ID único de Outlook.');
if (!payerName) errors.push('No se obtuvo el nombre del pagador.');
if (!amount) errors.push('No se obtuvo el valor del pago.');
if (!accountLast4) errors.push('No se identificó una cuenta receptora autorizada.');

return [{
  json: {
    config: CONFIG,
    candidate: senderAllowed || brandAndOperation,
    valid: errors.length === 0,
    errors,
    payload: {
      outlookMessageId,
      internetMessageId: internetMessageId || null,
      sender,
      subject,
      payerName,
      amount,
      currency: 'COP',
      accountLast4,
      bankReference: bankReference || null,
      receivedAt,
      rawPayload: {
        bodyPreview: body.slice(0, 3500),
      },
    },
  },
}];

const source = $('Extraer datos bancarios').item.json;
const response = $json?.body ?? $json ?? {};
const action = String(response.action ?? 'REVIEW_REQUIRED');

const amount = Number(source.payload.amount ?? 0).toLocaleString('es-CO', {
  style: 'currency',
  currency: 'COP',
  maximumFractionDigits: 0,
});

const esc = (value) =>
  String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');

const tenant = response.tenant ?? {};
const property = response.property ?? {};
const invoice = response.invoice ?? {};

const confirmationHtml = `
<!doctype html>
<html lang="es">
<body style="font-family:Arial,sans-serif;line-height:1.55;color:#222">
  <h2>Confirmación de pago recibido</h2>
  <p>Hola, <strong>${esc(tenant.name || 'arrendatario')}</strong>.</p>
  <p>El pago fue conciliado con la información de tu contrato:</p>
  <table cellpadding="6" cellspacing="0" style="border-collapse:collapse">
    <tr><td><strong>Valor</strong></td><td>${esc(amount)}</td></tr>
    <tr><td><strong>Pagador</strong></td><td>${esc(source.payload.payerName)}</td></tr>
    <tr><td><strong>Cuenta receptora</strong></td><td>Terminada en ${esc(source.payload.accountLast4)}</td></tr>
    <tr><td><strong>Referencia</strong></td><td>${esc(response.reference || source.payload.bankReference || source.payload.outlookMessageId)}</td></tr>
    <tr><td><strong>Factura</strong></td><td>${esc(invoice.code)}</td></tr>
    <tr><td><strong>Inmueble</strong></td><td>${esc(property.address)}</td></tr>
  </table>
  <p>Conserva el comprobante bancario. La confirmación podrá revisarse si el banco reporta reversión o inconsistencia.</p>
  <p>Cordialmente,<br><strong>BUIJO — Administración de arrendamientos</strong></p>
</body>
</html>`;

return [{
  json: {
    ...source,
    apiResponse: response,
    result: {
      action,
      confirmed: action === 'CONFIRMED' && Boolean(tenant.email),
      duplicate: action === 'DUPLICATE',
      needsReview: !['CONFIRMED', 'DUPLICATE'].includes(action),
      reason: String(response.reason ?? 'Sin motivo informado'),
    },
    confirmation: {
      to: String(tenant.email ?? ''),
      subject: `Confirmación de pago - ${response.reference || source.payload.bankReference || source.payload.outlookMessageId}`,
      html: confirmationHtml,
    },
  },
}];
